class EmailHealthSignal(BaseModel):
    model_config = ConfigDict(extra="allow")
    metric: Annotated[EmailHealthSignalMetric, Field(
        description="Which rate this signal reports.",
        examples=["bounce_rate"],
        min_length=1,
    )]
