class DomainStatus(str, Enum):
    pending = "pending"
    verified = "verified"
    failed = "failed"
    temporary_failure = "temporary_failure"
    rejected = "rejected"


class Domain(BaseModel):
    model_config = ConfigDict(extra="allow")
    id: Annotated[str, Field(
        examples=["dom_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^dom_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    workspace_id: Annotated[str, Field(
        examples=["ws_01krdgeqcxet5s7t44vh8rt9mg"],
        min_length=1,
        pattern="^ws_[0-9a-hjkmnp-tv-z]{26}$",
    )]
    domain: Annotated[str, Field(
        description="The sending domain name. Set at creation and immutable.",
        examples=["mail.acme.com"],
        min_length=1,
    )]
    vendor: Annotated[DomainVendor, Field(
        description="The DNS provider hosting this domain's nameservers, so you know which provider's dashboard to manage the required DNS records in. Returns `other` when the provider has not been detected or is not recognized.",
        min_length=1,
    )]
    status: Annotated[DomainStatus, Field(
        description="Domain ownership verification, proven by the DKIM record. Readiness to\nsend or track is reported separately per capability under\n`capabilities.*.status`.\n\n- `pending`: the DKIM record has not been published yet.\n- `verified`: the DKIM record is in place; ownership is confirmed.\n- `failed`: a DKIM record exists but does not match the expected\n  value (for example a stale record from an earlier setup), or a\n  previously verified record was removed. Correct the record to\n  recover.\n- `temporary_failure`: DNS resolution failed transiently, such as from a\n  timeout or unreachable nameserver. Verification retries automatically;\n  do not change the DNS records unless they are incorrect.\n- `rejected`: the domain was refused for policy reasons and cannot be\n  used for sending. Contact support if you believe this is an error.",
        min_length=1,
    )]
    settings: Annotated[DomainSettings, Field(
        description="Per-domain behavior toggles. Changes apply immediately to new sends.",
    )]
    next: Annotated[Optional[List[NextAction]], Field(
        description="What to do next about this domain, given the state it is in. Each entry names one action and says\nwhy it is worth taking, so you can act on this response without working out the order\nyourself. Present on reads that compute it: an empty list means there is nothing to do,\nand the field is absent entirely on responses that do not report next actions.\n\nThis answers whether you own the domain, which is what `status` reports. What each\ncapability still needs before it can send or receive is reported separately under\n`capabilities`, so an empty list here does not on its own mean the domain is ready.",
    )] = None
    dkim: Annotated[DomainDKIM, Field(
        description="Active DKIM signing configuration for the domain.",
    )]
    capabilities: DomainCapabilities
    dns_records: Annotated[List[DNSRecord], Field(
        description="The domain's DNS records and their individual verification state, returned in full on both the list and single-domain responses. This is the complete set to publish across DKIM, return-path, DMARC, tracking, and inbound; records for a staged change carry `state: pending`. Inbound MX records are always included as a regional reference, even while receiving is off and `capabilities.inbound.status` is `not_configured`. Their presence alone does not mean receiving is enabled; see `DomainUpdate.inbound`.",
    )]
    last_checked_at: Annotated[Optional[str], Field(
        description="When we last checked this domain's DNS records, whether or not the outcome changed. Updated on every verification: your manual refresh and the periodic automatic re-checks alike. `null` if the domain has never been checked.",
    )] = None
    verified_at: Annotated[Optional[str], Field(
        description="When the domain's ownership was confirmed: the moment `status` became `verified` via the DKIM record. Unchanged by later re-checks while it stays verified. `null` if the domain has never been verified.",
    )] = None
    created_at: Annotated[str, Field(
        description="When the domain was added.",
        min_length=1,
    )]
    updated_at: Annotated[str, Field(
        description="When the domain's configuration was last changed (such as a settings or return-path change). Verification re-checks do not change this; see `last_checked_at` and `verified_at` for verification timing.",
        min_length=1,
    )]


